/* BEGIN empty section spacing v1: all direct questions must carry the trusted empty marker.
   Exact section ids, child counts and heading position reject mixed/unknown
   structures. Only print margins change; retain empty answer boxes and all text.
   One-step :has predicates avoid the unmatching descendant-chain diagnostic. */
@media print {
html body #dmp-content > section.dmp-section#sec-data-collection:has(> h2:first-child):has(> div.question.compact-empty-question:nth-child(2)):has(> div.question.compact-empty-question:nth-child(3):last-child),
html body #dmp-content > section.dmp-section#sec-docs-metadata:has(> h2:first-child):has(> div.question.compact-empty-question:nth-child(2)):has(> div.question.compact-empty-question:nth-child(3):last-child),
