html body #dmp-content > section.dmp-section#sec-ethics-legal:has(> h2:first-child):has(> div.question.compact-empty-question:nth-child(2)):has(> div.question.compact-empty-question:nth-child(3)):has(> div.question.compact-empty-question:nth-child(4):last-child),
html body #dmp-content > section.dmp-section#sec-sharing-preservation:has(> h2:first-child):has(> div.question.compact-empty-question:nth-child(2)):has(> div.question.compact-empty-question:nth-child(3)):has(> div.question.compact-empty-question:nth-child(4)):has(> div.question.compact-empty-question:nth-child(5):last-child),
